sys_script_include.script:
var IssueUtilBase = Class.create();

IssueUtilBase.prototype = {
    initialize: function() {

        this.POLICY_EXCEPTION_NEW_STATE = 1; //Considered an Open State
        this.POLICY_EXCEPTION_ANALYZE_STATE = 2; //Considered an Open State
        this.POLICY_EXCEPTION_CLOSED_STATE = 3;
        this.POLICY_EXCEPTION_AWAITING_APPROVAL_STATE = 6; //Considered an Open State
        this.POLICY_EXCEPTION_REJECTED_STATE = 7;
        this.POLICY_EXCEPTION_APPROVED_STATE = 8; //Considered an Open State
        this.POLICY_EXCEPTION_RISK_ASSESSMENT_STATE = 10;
        this.POLICY_EXCEPTION_REVIEW_STATE = 12; //Considered an Open State

        this.POLICY_EXCEPTION_CANCELED_SUBSTATE = 30; //Considered an Open State

        this.ISSUE_REVIEW_STATE = 0;
        this.ISSUE_NEW_STATE = 1;
        this.ISSUE_ANALYZE_STATE = 2;
        this.ISSUE_CLOSED_COMPLETE_STATE = 3;
        this.ISSUE_CLOSED_INCOMPLETE_STATE = 4;
        this.ISSUE_RESPOND_STATE = 5;

        this.ISSUE_RESPONSE_REMEDIATE_STATE = 1;
        this.ISSUE_RESPONSE_ACCEPT_STATE = 2;

        this.REMEDIATION_TASK_OPEN_STATE = 1; //Considered an Open State
        this.REMEDIATION_TASK_RESPOND_STATE = 2; //Considered an Open State
        this.REMEDIATION_TASK_CLOSED_COMPLETE_STATE = 3;
        this.REMEDIATION_TASK_CLOSED_INCOMPLETE_STATE = 4;
        this.REMEDIATION_TASK_CLOSED_CANCELLED_STATE = 7;
        this.REMEDIATION_TASK_WORK_IN_PROGRESS_STATE = 8; //Considered an Open State
        this.REMEDIATION_TASK_REVIEW_STATE = 9;

    },

    ProcessActionPlanByIssue: function(Issue) { 

		var queryString = "stateIN" + this.REMEDIATION_TASK_CLOSED_COMPLETE_STATE + "," + 
		this.REMEDIATION_TASK_CLOSED_INCOMPLETE_STATE + "," +
		this.REMEDIATION_TASK_CLOSED_CANCELLED_STATE; //TSB02

        var remediation_task = new GlideRecord('sn_grc_task');
        remediation_task.addQuery('issue.sys_id', '=', Issue);
        //remediation_task.addQuery('state', '=', this.REMEDIATION_TASK_CLOSED_COMPLETE_STATE); //Closed Complete
		remediation_task.addEncodedQuery(queryString); //Closed Complete, Closed Incomplete, Closed Cancelled - TSB02
        remediation_task.setLimit(1);
        remediation_task.orderByDesc('sys_updated_on');
        remediation_task.query();

        if (remediation_task.next()) {

            var issue = new GlideRecord('sn_grc_issue');
            issue.addQuery('sys_id', '=', Issue);
            issue.query();

            if (issue.next()) {
                //var _action_plan = issue.getValue('action_plan');
                //issue.work_notes = _action_plan;
                issue.action_plan = "";
                issue.update();
            }

        }

    },

    AttestationQuestionChange: function(oldValue, newValue, metric_id) {
        var ret_val = false;
        if (oldValue == 0 && (newValue == 1 || newValue == 2)) {
            var grMetric = new GlideRecord('asmt_metric');
            grMetric.addQuery('sys_id', metric_id);
            grMetric.query();
            if (grMetric.next()) {
                var question = grMetric.getValue('question');
                if (question == "Is the control Implemented?") {
                    ret_val = true;
                }
            }
        }
        return ret_val;

    },

    UpdateIssueAssignToByEntity: function(EntityID, NewSupportedBy, OldSupportedBy) {

        var compliance_control = new GlideRecord('sn_compliance_control'); //Control
        compliance_control.addEncodedQuery('profile.sys_id=' + EntityID);
        compliance_control.query();
        while (compliance_control.next()) {

            var control = compliance_control.getValue('sys_id');

            var issue = new GlideRecord('sn_grc_issue');
            issue.addQuery('item.sys_id', '=', control);
            issue.addQuery('assigned_to', '=', OldSupportedBy);
            issue.addQuery('state', 'NOT IN', '3,4'); //Closed Complete,Closed Incomplete
            issue.query();

            if (issue.next()) {

                issue.assigned_to = NewSupportedBy; //Set New Supported By
                issue.update();

            }

        }

        return true;

    },
    /**********************************************************************************************************************
     * Change history:
     * Change ID	Name				Date		Description
     * ES01			Evan Somerstein		04/26/24	GRC_IROC-5082 - Updating Issue Query to only look at the active Issue
     * ES02			Evan Somerstein		06/20/24	GRC_IROC-5746 - Updating to clear the exempt field from the sn_compliance_control
     **********************************************************************************************************************/
    CloseIssueRemediationTaskPolicyExceptionByControl: function(Control) {

        var issue = new GlideRecord('sn_grc_issue');
        //issue.addQuery('item.sys_id', '=', Control);
        issue.addQuery('item', '=', Control);
        issue.addQuery('active', '=', 'true'); // ES01 - Close only the active issue. Other issues are already closed
        issue.query();

        if (issue.next()) {
            var Issue = issue.getValue('sys_id');

            var policyExceptionResult = this.ClosePolicyExceptionByIssue(Issue);
            var remediationTaskResult = this.CloseRemediationTaskByIssue(Issue);

            if (issue.state != this.ISSUE_CLOSED_COMPLETE_STATE) { //Issue Not In Closed Complete
                issue.state = this.ISSUE_CLOSED_INCOMPLETE_STATE; //Closed Incomplete
                issue.update();
            }
            // ES02 Start
            // Get the Compliance Control record
            var grControl = new GlideRecord('sn_compliance_control');
            grControl.addQuery('sys_id', Control);
            grControl.query();
            if (grControl.next()) {
                // Clear the exempt flag
                grControl.setValue('exempt', false);
                grControl.update();
            }
            // ES02 ENd

        }

        return true;

    },

    GetPolicyExceptionByIssue: function(Issue) {

        PolicyExceptionArray = [];

        var policy_exception = new GlideRecord('sn_compliance_policy_exception');
        policy_exception.addQuery('issue.sys_id', '=', Issue);
        policy_exception.addQuery('state', 'IN', '1,2,6,12'); //New,Analyze,Awaiting Approval,Review
        policy_exception.setLimit(1);
        policy_exception.orderByDesc('sys_updated_on');
        policy_exception.query();

        while (policy_exception.next()) {

            var _number = policy_exception.getValue('number');
            var _policy_exception_sys_id = policy_exception.getValue('sys_id');
            var _state = policy_exception.getValue('state');
            var _state_display = policy_exception.getDisplayValue('state');

            var PolicyExceptionObject = {
                sys_id: _policy_exception_sys_id,
                number: _number,
                state: _state,
                state_display: _state_display
            };

            PolicyExceptionArray.push(PolicyExceptionObject);

        }

        return PolicyExceptionArray;
    },

    //GRC_IROC-5252
