    ClosePolicyExceptionByIssue: function(Issue) {

        var policy_exception = new GlideRecord('sn_compliance_policy_exception');
        policy_exception.addQuery('issue.sys_id', '=', Issue);
        policy_exception.addQuery('state', 'NOT IN', '3,7'); //Closed,Rejected
        policy_exception.orderByDesc('sys_updated_on');
        policy_exception.query();

        while (policy_exception.next()) {

            policy_exception.state = 3; //Closed
            policy_exception.substate = 30; //Canceled
            policy_exception.update();

        }

        return true;

    },

    GetRemediationTaskByIssue: function(Issue) {

        RemediationTaskArray = [];

        var remediation_task = new GlideRecord('sn_grc_task');
        remediation_task.addQuery('issue.sys_id', '=', Issue);
        remediation_task.addQuery('state', 'IN', '1,2,8'); //Open,Respond,Work in Progress
        remediation_task.setLimit(1);
        remediation_task.orderByDesc('sys_updated_on');
        remediation_task.query();

        while (remediation_task.next()) {

            var _number = remediation_task.getValue('number');
