    CloseRemediationTaskByIssue: function(Issue) {

        var remediation_task = new GlideRecord('sn_grc_task');
        remediation_task.addQuery('issue.sys_id', '=', Issue);
        remediation_task.addQuery('state', 'NOT IN', '3,4,7'); //Closed Complete,Closed Incomplete,Closed Cancelled
        remediation_task.orderByDesc('sys_updated_on');
        remediation_task.query();

        while (remediation_task.next()) {
            remediation_task.state = 4; //Closed Incomplete
            remediation_task.update();

        }

        return true;

    },

    GetClosedCompleteRemediationTaskByIssue: function(Issue) {

        RemediationTaskArray = [];

        var remediation_task = new GlideRecord('sn_grc_task');
