    /**********************************************************************************************************************
     * Change history:
     * Change ID	Name				Date		Description
     * ES01			Evan Somerstein		04/26/24	GRC_IROC-5082 - Updating to only use the most recent remediation task
     * 												and policy exception for determining status
     * ALC01		Alex Leon			05/16/24	GRC_IROC-5253 - _state != 4 was remove to allow LM Control Compliance status to change to 
     * 												Not Compliant when an Issue is Closed Incomplete
     * TSB01		Torrance Brown      05/26/24    GRC_IROC-5252 - Set LM Control Compliance Status to Compliant With Policy Exception
     **********************************************************************************************************************/

    SetControlComplianceStatusByIssue: function(Issue) {

        var entityUtilBase = new EntityUtilBase();
        var result = null;
        var SetIssueToReview = false;

        var issue = new GlideRecord('sn_grc_issue');
        issue.addQuery('sys_id', '=', Issue);
        issue.query();

        if (issue.next()) {
            var _item = issue.getValue('item');
            var _response = issue.getValue('response');
            var _state = issue.getValue('state');

            // var RemediationTaskArray = this.GetRemediationTaskByIssue(Issue); - ES01
            var MostRecentRemediationTaskArray = this.GetMostRecentRemediationTaskByIssue(Issue); // - ES01
            // var ClosedCompleteRemediationTaskArray = this.GetClosedCompleteRemediationTaskByIssue(Issue); - ES01

            ///			if(RemediationTaskArray.length > 0 || ClosedCompleteRemediationTaskArray.length > 0) { - ES01
            if (MostRecentRemediationTaskArray.length > 0) { // - ES01

                if (_response == 1 && _state == 5) { // Open Remediation Task Exists With Respond/Remediate Action Plan
                    result = entityUtilBase.SetControlComplianceStatus(_item, 'compliant_with_poam');
                    /*
                    					if(ClosedCompleteRemediationTaskArray[0].state == 3 || 
                    					ClosedCompleteRemediationTaskArray[0].state == 4 || 
                    					ClosedCompleteRemediationTaskArray[0].state == 7) { // Check If Closed Complete,Closed Incomplete,Closed Cancelled 
                    					- ES 01 */
                    if (MostRecentRemediationTaskArray[0].state == 3 ||
                        MostRecentRemediationTaskArray[0].state == 4 ||
                        MostRecentRemediationTaskArray[0].state == 7) { // Check If Closed Complete,Closed Incomplete,Closed Cancelled
                        SetIssueToReview = true;
                    }
                } else if (_state == 3) { // Check If Issue In Closed Complete With A Remediation Task
                    result = entityUtilBase.SetControlComplianceStatus(_item, 'compliant');
                    // ES01 - Do not set compliance status if issue is closed incomplete.  Status will be set elsewhere
                } else if (_response == 1 && (_state != 0 && _state != 5)) { // Check If Issue Not In Review or Respond or Closed Incomplete
                    //ALC01 - _state != 4 remove
                    result = entityUtilBase.SetControlComplianceStatus(_item, 'not_compliant');
                }

            } else {

                //var PolicyExceptionArray = this.GetPolicyExceptionByIssue(Issue);
                var MostRecentPolicyExceptionArray = this.GetMostRecentPolicyExceptionByIssue(Issue); //GRC_IROC-5252

                if (MostRecentPolicyExceptionArray.length > 0) { // No Open Remediation Task Exists and Open Policy Exception Exists

                    if (MostRecentPolicyExceptionArray[0].state == this.POLICY_EXCEPTION_APPROVED_STATE) { //TSB01

                        result = entityUtilBase.SetControlComplianceStatus(_item, 'compliant_with_policy_exception');

                    } else {

                        result = entityUtilBase.SetControlComplianceStatus(_item, 'not_compliant');

                    }

                } else {

                    result = entityUtilBase.SetControlComplianceStatus(_item, 'not_compliant');

                    /*if(current.response == 0) {
                    	result = entityUtilBase.SetControlComplianceStatus(current.item, 'not_compliant');
                    }
                    else if(current.response == 1 && current.state != 5) {
                    	result = entityUtilBase.SetControlComplianceStatus(current.item, 'not_compliant');
                    }
                    else if(current.response == 2) {
                    	result = entityUtilBase.SetControlComplianceStatus(current.item, 'not_compliant');
                    }
                    else if(current.response == 3) {
                    	result = entityUtilBase.SetControlComplianceStatus(current.item, 'not_compliant');
                    }
                    else if(current.response == 4) {
                    	result = entityUtilBase.SetControlComplianceStatus(current.item, 'not_compliant');
                    }
                    else if(current.response == 5) {
                    	result = entityUtilBase.SetControlComplianceStatus(current.item, 'not_compliant');
                    }*/

                }

            }

            if (SetIssueToReview) { // Set Issue To Review
                issue.state = 0;
                issue.update();
            }

        }

        return true;

    },

    remediationTaskExists: function(parentSysId) {
        var encodedQuery = "issue=" + parentSysId +
            "^state=" + this.REMEDIATION_TASK_OPEN_STATE +
            "^ORstate=" + this.REMEDIATION_TASK_RESPOND_STATE +
            "^ORstate=" + this.REMEDIATION_TASK_WORK_IN_PROGRESS_STATE +
            "^ORstate=" + this.REMEDIATION_TASK_REVIEW_STATE;

        var isRemediationTaskFound = false;
        var remediationTask = new GlideAggregate('sn_grc_task');
        remediationTask.setGroup(false);
        remediationTask.addAggregate('COUNT', 'sys_mod_count');
        remediationTask.addEncodedQuery(encodedQuery);
        remediationTask.query();

        if (remediationTask.next()) {
            var remediationTaskCount = remediationTask.getAggregate('COUNT', 'sys_mod_count');

            if (remediationTaskCount == 0)
                isRemediationTaskFound = false;
            else
                isRemediationTaskFound = true;
        }

        return isRemediationTaskFound;
    },

    /**********************************************************************************************************************
     * Change history:
     * Change ID	Name				Date		Description
     * TAB01		Tonny Boesenbaek	05/15/2024	GRC_IROC-5228 - 'Approved' state is now considered a closed state
     **********************************************************************************************************************/
    policyExceptionExists: function(parentSysId) {
        var encodedQuery = "issue=" + parentSysId +
            "^state=" + this.POLICY_EXCEPTION_NEW_STATE +
            "^ORstate=" + this.POLICY_EXCEPTION_ANALYZE_STATE +
            "^ORstate=" + this.POLICY_EXCEPTION_AWAITING_APPROVAL_STATE +
            "^ORstate=" + this.POLICY_EXCEPTION_RISK_ASSESSMENT_STATE +
            "^ORstate=" + this.POLICY_EXCEPTION_REVIEW_STATE;
        //"^ORstate=" + this.POLICY_EXCEPTION_APPROVED_STATE; TAB01

        var isPolicyExceptionFound = false;
        var policyException = new GlideAggregate('sn_compliance_policy_exception');
        policyException.setGroup(false);
        policyException.addAggregate('COUNT', 'sys_mod_count');
        policyException.addEncodedQuery(encodedQuery);
        policyException.query();

        if (policyException.next()) {
            var policyExceptionCount = policyException.getAggregate('COUNT', 'sys_mod_count');

            if (policyExceptionCount == 0)
                isPolicyExceptionFound = false;
            else
                isPolicyExceptionFound = true;
        }

        return isPolicyExceptionFound;
    },

    updatePolicyExceptionRequester: function(newRequester, oldRequester, busAppSysId) {
        var grPE = new GlideRecord('sn_compliance_policy_exception');

        // issue.profile.applies_to dot-walks to Entity's field that stores the sys_id of the Business Application associated with an Entity
        var encodedQuery = 'issue.profile.applies_to=' + busAppSysId +
            '^state=' + this.POLICY_EXCEPTION_NEW_STATE +
            '^ORstate=' + this.POLICY_EXCEPTION_ANALYZE_STATE +
            "^ORstate=" + this.POLICY_EXCEPTION_AWAITING_APPROVAL_STATE +
            "^ORstate=" + this.POLICY_EXCEPTION_RISK_ASSESSMENT_STATE +
            "^ORstate=" + this.POLICY_EXCEPTION_REVIEW_STATE +
            "^ORstate=" + this.POLICY_EXCEPTION_APPROVED_STATE;

        grPE.addEncodedQuery(encodedQuery);

        grPE.query();
        while (grPE.next()) {
            if (grPE.opened_by == oldRequester) {
                grPE.opened_by = newRequester;
                grPE.update();
            }
        }
    },
    /**********************************************************************************************************************
     * Change history:
     * Change ID	Name				Date		Description
     * ALC01		Alex Leon			4/25/2024	GGRC_IROC 4329 -  Remediation Tasks Downstream update - script created
     * ALC02		Alex Leon			4/29/2024   Opened_by change to assigned_to
     **********************************************************************************************************************/
    //ALC01

    updateRemediationTaskRequester: function(newRequester, oldRequester, busAppSysId) {
        var grRT = new GlideRecord('sn_grc_task');

        var encodedQuery = 'issue.profile.applies_to=' + busAppSysId +
            '^state=' + this.REMEDIATION_TASK_OPEN_STATE + //Considered an Open State
            '^ORstate=' + this.REMEDIATION_TASK_RESPOND_STATE + //Considered an Open State
            '^ORstate=' + this.REMEDIATION_TASK_WORK_IN_PROGRESS_STATE + //Considered an Open State
            '^ORstate=' + this.REMEDIATION_TASK_REVIEW_STATE;


        grRT.addEncodedQuery(encodedQuery);

        grRT.query();

        while (grRT.next()) {
            if (grRT.assigned_to == oldRequester) { //ALC02 opened_by change to assigned_to
                grRT.assigned_to = newRequester; //ALC02 opened_by change to assigned_to
                grRT.update();
            }
        }
    },

    type: 'IssueUtilBase'
};
